package android.text;public class SpannableStringBuilder implements CharSequence{private final StringBuilder s=new StringBuilder();public SpannableStringBuilder append(char c){s.append(c);return this;}public SpannableStringBuilder append(CharSequence c){s.append(c);return this;}public int length(){return s.length();}public char charAt(int i){return s.charAt(i);}public CharSequence subSequence(int a,int b){return s.subSequence(a,b);}public void setSpan(Object a,int b,int c,int d){}public String toString(){return s.toString();}}